'use strict';

/**
* Compute the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm, and returning the number of non-`NaN` elements.
*
* @module @stdlib/blas/ext/base/snannsumkbn
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var Int32Array = require( '@stdlib/array/int32' );
* var snannsumkbn = require( '@stdlib/blas/ext/base/snannsumkbn' );
*
* var x = new Float32Array( [ 1.0, -2.0, NaN, 2.0 ] );
* var sum = new Float32Array( 1 );
* var count = new Int32Array( 1 );
*
* var v = snannsumkbn( x.length, x, 1, sum, count );
* // returns <Float32Array>[ 1.0 ]
*
* var n = count[ 0 ];
* // returns 3
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var Int32Array = require( '@stdlib/array/int32' );
* var snannsumkbn = require( '@stdlib/blas/ext/base/snannsumkbn' );
*
* var x = new Float32Array( [ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0, NaN, NaN ] );
* var sum = new Float32Array( 1 );
* var count = new Int32Array( 1 );
*
* var v = snannsumkbn.ndarray( 5, x, 2, 1, sum, 0, count, 0 );
* // returns <Float32Array>[ 5.0 ]
*
* var n = count[ 0 ];
* // returns 4
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var snannsumkbn;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	snannsumkbn = main;
} else {
	snannsumkbn = tmp;
}


// EXPORTS //

module.exports = snannsumkbn;

// exports: { "ndarray": "snannsumkbn.ndarray" }
